column1:
layout(location = 0) in vec3 in_position;
layout(location = 1) in vec2 in_uv;

out vec2 v_uv;
out vec3 v_xyz;

uniform mat4 mvp;

void main() {
    gl_Position = mvp * vec4(in_position.x, in_position.y, in_position.z, 1.0);
    v_xyz = in_position.xyz;
    v_uv = in_uv;
}

