column1:
in vec4 v_color;

out vec4 out_color;

uniform vec4 u_color_mod = vec4(1.0, 1.0, 1.0, 1.0);
uniform vec4 u_color_add = vec4(0.0, 0.0, 0.0, 0.0);

void main() {
    out_color = v_color;

    out_color *= u_color_mod;
    out_color += u_color_add;
}

